# ── A1: move_end_effector_to_position ──────────────────────────────────

def move_end_effector_to_position(self, request: dict) -> dict:
    """Regulate EE to a world-frame position within max_duration_s."""
    target = np.array(request["target_position_m"], dtype=float)
    max_dur = float(request["max_duration_s"])

    # validate
    if not np.all(np.isfinite(target)):
        raise CapabilityError("A1: target_position_m contains non-finite values")
    if not (0.25 <= max_dur <= 8.0):
        raise CapabilityError(f"A1: max_duration_s={max_dur} out of [0.25, 8]")

    deadline = self._now() + max_dur
    ok = self._regulate_to(target, deadline, hold_s=0.5, tol=0.015)
    if not ok:
        # stop motion – hold current arm pose
        self.set_arm_actuators(self.get_joint_positions())
        raise CapabilityError(
            f"A1: could not reach target within {max_dur}s; "
            f"final error={np.linalg.norm(self._ee_pos()-target):.4f}m"
        )
    return {"status": "success", "final_error_m": float(np.linalg.norm(self._ee_pos() - target))}

# ── A2: trace_cartesian_path ───────────────────────────────────────────

def trace_cartesian_path(self, request: dict) -> dict:
    """Visit waypoints in order with bounded cross-track error."""
    waypoints = [np.array(w, dtype=float) for w in request["waypoints_m"]]
    seg_dur   = float(request["max_duration_per_segment_s"])

    if not (0.25 <= seg_dur <= 5.0):
        raise CapabilityError(f"A2: max_duration_per_segment_s={seg_dur} out of [0.25, 5]")
    for i, w in enumerate(waypoints):
        if not np.all(np.isfinite(w)):
            raise CapabilityError(f"A2: waypoint {i} contains non-finite values")

    max_cross = 0.0
    for idx, wp in enumerate(waypoints):
        deadline = self._now() + seg_dur
        is_last  = (idx == len(waypoints) - 1)
        hold_s   = 0.5 if is_last else 0.0
        tol      = 0.015 if is_last else 0.02

        # track cross-track error during approach
        prev_wp = waypoints[idx - 1] if idx > 0 else self._ee_pos()
        seg_vec = wp - prev_wp
        seg_len = float(np.linalg.norm(seg_vec))

        hold_start: float | None = None
        reached = False
        while self._now() < deadline:
            pos = self._ee_pos()
            err = float(np.linalg.norm(pos - wp))

            # cross-track: distance from pos to the line segment
            if seg_len > 1e-6:
                t = float(np.clip(np.dot(pos - prev_wp, seg_vec) / (seg_len ** 2), 0.0, 1.0))
                closest = prev_wp + t * seg_vec
                ct = float(np.linalg.norm(pos - closest))
                max_cross = max(max_cross, ct)

            if err <= tol:
                if is_last:
                    if hold_start is None:
                        hold_start = self._now()
                    elif self._now() - hold_start >= hold_s:
                        reached = True
                        break
                else:
                    reached = True
                    break
            else:
                hold_start = None

            q_sol = self.ik(wp)
            if q_sol is not None:
                self.set_arm_actuators(q_sol)
            self.step(1)

        if not reached:
            self.set_arm_actuators(self.get_joint_positions())
            raise CapabilityError(
                f"A2: waypoint {idx} not reached within {seg_dur}s; "
                f"error={np.linalg.norm(self._ee_pos()-wp):.4f}m"
            )

    return {"status": "success", "max_cross_track_m": max_cross,
            "final_error_m": float(np.linalg.norm(self._ee_pos() - waypoints[-1]))}

